description:
Filtering a huge log every frame is too slow. Keep a list of the indexes of lines that pass, update it only for new lines, and rebuild it only when the filter changes:

```cpp
class FilteredLog
{
public:
    void add(const std::string& line);
    void setFilter(const std::string& filter);           // rebuilds the visible list
    const std::vector<int>& visible() const;            // indexes of passing lines, in order
    int checks() const;                                  // how many times a line was tested against the filter
};
```

Use lesson 5.02's filter rules (write them again, or reuse your `TextFilter`). `checks` counts every test of one line against the filter, so the tests can see that adding a line costs one check and that changing the filter costs one check per line, not more.

starter.solution.cpp:
#include <string>
#include <vector>

class FilteredLog
{
public:
    void add(const std::string& line) {}
    void setFilter(const std::string& filter) {}
    const std::vector<int>& visible() const { return m_visible; }
    int checks() const { return 0; }
private:
    std::vector<int> m_visible;
};

solution.solution.cpp:
#include <cctype>
#include <string>
#include <vector>

class FilteredLog
{
public:
    void add(const std::string& line)
    {
        m_lines.push_back(line);
        if (passes(line)) m_visible.push_back(static_cast<int>(m_lines.size()) - 1);
    }

    void setFilter(const std::string& filter)
    {
        m_terms.clear();
        m_inclusions = 0;
        std::string term;
        auto finish = [&] {
            const auto a{ term.find_first_not_of(' ') };
            if (a != std::string::npos)
            {
                std::string t{ term.substr(a, term.find_last_not_of(' ') - a + 1) };
                if (t != "-") { m_terms.push_back(t); if (t[0] != '-') ++m_inclusions; }
            }
            term.clear();
        };
        for (char c : filter) { if (c == ',') finish(); else term += c; }
        finish();
        m_visible.clear();
        for (int i{ 0 }; i < static_cast<int>(m_lines.size()); ++i)
            if (passes(m_lines[static_cast<std::size_t>(i)])) m_visible.push_back(i);
    }

    const std::vector<int>& visible() const { return m_visible; }
    int checks() const { return m_checks; }

private:
    static std::string lower(std::string s)
    {
        for (char& c : s) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
        return s;
    }

    bool passes(const std::string& line)
    {
        ++m_checks;
        if (m_terms.empty()) return true;
        const std::string hay{ lower(line) };
        for (const std::string& t : m_terms)
        {
            const bool exclude{ t[0] == '-' };
            if (hay.find(lower(exclude ? t.substr(1) : t)) != std::string::npos) return !exclude;
        }
        return m_inclusions == 0;
    }

    std::vector<std::string> m_lines;
    std::vector<std::string> m_terms;
    int m_inclusions{ 0 };
    std::vector<int> m_visible;
    int m_checks{ 0 };
};

unitTests:
TEST("no filter") { FilteredLog l; l.add("a"); l.add("b"); CHECK_EQ(l.visible(), (std::vector<int>{ 0, 1 })); CHECK_EQ(l.checks(), 2); }
TEST("set a filter") { FilteredLog l; l.add("texture ok"); l.add("audio ok"); l.add("texture missing"); l.setFilter("-missing,texture"); CHECK_EQ(l.visible(), (std::vector<int>{ 0 })); CHECK_EQ(l.checks(), 6); }
TEST("new lines cost one check") { FilteredLog l; l.setFilter("error"); l.add("ok"); l.add("ERROR: disk"); l.add("fine"); CHECK_EQ(l.visible(), (std::vector<int>{ 1 })); CHECK_EQ(l.checks(), 3); }
TEST("clearing the filter") { FilteredLog l; l.setFilter("x"); l.add("a"); l.add("x"); l.setFilter(""); CHECK_EQ(l.visible(), (std::vector<int>{ 0, 1 })); }

